スタックの TDD 実装比較 <pre><code>;; Clojure: リストベース
(defn create-stack [] '())
(defn stack-push [stack item] (conj stack item))
(defn stack-pop [stack] [(first stack) (rest stack)])

(deftest test-stack
  (let [stack (-&gt; (create-stack) (stack-push "a") (stack-push "b"))
        [top remaining] (stack-pop stack)]
    (is (= "b" top))
    (is (= '("a") remaining))))
</code></pre> <pre><code>// Scala: case class + List
case class Stack[A](items: List[A] = Nil):
  def push(item: A): Stack[A] = Stack(item :: items)
  def pop: (A, Stack[A]) = (items.head, Stack(items.tail))

test("push して pop すると LIFO") {
  val stack = Stack[String]().push("a").push("b")
  val (top, remaining) = stack.pop
  top shouldBe "b"
  remaining.pop._1 shouldBe "a"
}
</code></pre> <pre><code>// Rust: Vec ベース + 不変メソッド
pub struct Stack&lt;T: Clone&gt; {
    items: Vec&lt;T&gt;,
}

impl&lt;T: Clone&gt; Stack&lt;T&gt; {
    pub fn empty() -&gt; Self { Stack { items: Vec::new() } }

    pub fn push(&amp;self, item: T) -&gt; Self {
        let mut new_items = self.items.clone();
        new_items.push(item);
        Stack { items: new_items }
    }

    pub fn pop(&amp;self) -&gt; Option&lt;(T, Self)&gt; {
        if self.items.is_empty() {
            None
        } else {
            let mut new_items = self.items.clone();
            let top = new_items.pop().unwrap();
            Some((top, Stack { items: new_items }))
        }
    }
}
</code></pre>

Clojure: 関数ベースの戦略 <pre><code>;; 戦略 = 単なる関数
(defn regular-pricing [amount] amount)
(defn discount-pricing [rate]
  (fn [amount] (* amount (- 1 rate))))
(defn member-pricing [amount]
  (* amount 0.9))
(defn bulk-pricing [threshold discount-rate]
  (fn [amount]
    (if (&gt;= amount threshold)
      (* amount (- 1 discount-rate))
      amount)))

;; コンテキスト
(defn calculate-total [items pricing-strategy]
  (let [subtotal (reduce + (map :price items))]
    (pricing-strategy subtotal)))

;; 使用
(calculate-total items (discount-pricing 0.2))
</code></pre> Scala: trait + 関数型ハイブリッド <pre><code>// trait ベース
trait PricingStrategy:
  def calculate(amount: Double): Double

object RegularPricing extends PricingStrategy:
  def calculate(amount: Double): Double = amount

class DiscountPricing(rate: Double) extends PricingStrategy:
  def calculate(amount: Double): Double = amount * (1 - rate)

// 関数ベース（より簡潔）
type PricingFn = Double =&gt; Double

val regular: PricingFn = identity
def discount(rate: Double): PricingFn = _ * (1 - rate)
def bulk(threshold: Double, rate: Double): PricingFn =
  amount =&gt; if amount &gt;= threshold then amount * (1 - rate) else amount

// 戦略の合成
def compose(strategies: PricingFn*): PricingFn =
  strategies.reduce(_ andThen _)
</code></pre> Haskell: newtype + モノイド <pre><code>newtype PricingStrategy = PricingStrategy { runStrategy :: Double -&gt; Double }

