  def init(config) do
    {:ok, %{state: :idle, transitions: config.transitions, log: []}}
  end

  def handle_call({:trigger, event}, _from, machine) do
    case get_transition(machine, event) do
      {next_state, action} -&gt;
        if action, do: action.()
        updated = %{machine |
          state: next_state,
          log: [{machine.state, event, next_state} | machine.log]}
