Java 実装（ReentrantLock） <pre><code>public class BankAccount {
    private final ReentrantLock lock = new ReentrantLock();
    private int balance;

    public void deposit(int amount) {
        lock.lock();
        try {
            balance += amount;
        } finally {
            lock.unlock();
        }
    }

    // デッドロック回避: identityHashCode 順でロック
    public static boolean transfer(BankAccount from, BankAccount to, int amount) {
        BankAccount first = System.identityHashCode(from) &lt; System.identityHashCode(to)
            ? from : to;
        BankAccount second = first == from ? to : from;

        first.lock.lock();
        try {
            second.lock.lock();
            try {
                if (from.balance &gt;= amount) {
                    from.balance -= amount;
                    to.balance += amount;
                    return true;
                }
                return false;
            } finally {
                second.lock.unlock();
            }
        } finally {
            first.lock.unlock();
        }
    }
}
