pub fn ranked_words&lt;'a, F&gt;(words: &amp;[&amp;'a str], word_score: F) -&gt; Vec&lt;&amp;'a str&gt;
where
    F: Fn(&amp;str) -&gt; i32,
{
    let mut result: Vec&lt;&amp;'a str&gt; = words.to_vec();
    result.sort_by(|a, b| word_score(b).cmp(&amp;word_score(a)));
    result
}

