操作 説明 例 <code>take(n)</code> 最初の n 要素を取得 <code>take(stream, 3)</code> <code>drop(n)</code> 最初の n 要素をスキップ <code>drop(stream, 2)</code> <code>filter(p)</code> 条件を満たす要素のみ <code>filterStream(stream, x =&gt; x &gt; 0)</code> <code>map(f)</code> 各要素を変換 <code>mapStream(stream, x =&gt; x * 2)</code> <code>takeWhile(p)</code> 条件を満たす間取得 <code>takeWhile(stream, x =&gt; x &lt; 10)</code> <code>sliding(n)</code> スライディングウィンドウ <code>sliding(stream, 3)</code> <pre><code>// 最初の n 要素を取得
const take = &lt;A&gt;(gen: LazyList&lt;A&gt;, n: number): readonly A[] =&gt; {
  const result: A[] = []
  let count = 0
  for (const item of gen) {
    if (count &gt;= n) break
    result.push(item)
    count++
  }
  return result
}

// 各要素を変換
function* mapStream&lt;A, B&gt;(
  gen: LazyList&lt;A&gt;,
  fn: (a: A) =&gt; B
): LazyList&lt;B&gt; {
  for (const item of gen) {
    yield fn(item)
  }
}

// 条件を満たす要素のみ
function* filterStream&lt;A&gt;(
  gen: LazyList&lt;A&gt;,
  predicate: (a: A) =&gt; boolean
): LazyList&lt;A&gt; {
  for (const item of gen) {
    if (predicate(item)) {
      yield item
    }
  }
}
</code></pre>

