                   ('SUP-001', 'テスト仕入先', '2')
            ON CONFLICT DO NOTHING
        """);
    }

    @Transactional
    public void cleanupTransactionData() {
        // トランザクションデータのクリーンアップ（外部キー制約の順序に注意）
