            c."オーダ種別" AS c_オーダ種別,
            c."品目コード" AS c_品目コード,
            c."着手予定日" AS c_着手予定日,
            c."納期" AS c_納期,
            c."計画数量" AS c_計画数量,
            c."ステータス" AS c_ステータス,
            -- 所要情報
            r."ID" AS r_ID,
            r."所要NO" AS r_所要NO,
            r."オーダID" AS r_オーダID,
            r."品目コード" AS r_品目コード,
            r."納期" AS r_納期,
            r."必要数量" AS r_必要数量,
            r."引当済数量" AS r_引当済数量,
            r."不足数量" AS r_不足数量,
            r."場所コード" AS r_場所コード,
            r."バージョン" AS r_バージョン,
            -- 引当情報
            a."ID" AS a_ID,
            a."所要ID" AS a_所要ID,
            a."引当区分" AS a_引当区分,
            a."オーダID" AS a_オーダID,
            a."引当日" AS a_引当日,
            a."引当数量" AS a_引当数量,
            a."場所コード" AS a_場所コード
        FROM "オーダ情報" o
        LEFT JOIN "基準生産計画" m ON o."MPS_ID" = m."ID"
        LEFT JOIN "オーダ情報" p ON o."親オーダID" = p."ID"
        LEFT JOIN "オーダ情報" c ON o."ID" = c."親オーダID"
        LEFT JOIN "所要情報" r ON o."ID" = r."オーダID"
        LEFT JOIN "引当情報" a ON r."ID" = a."所要ID"
        WHERE o."オーダNO" = #{orderNumber}
        ORDER BY c."ID", r."ID", a."ID"
    &lt;/select&gt;

&lt;/mapper&gt;
