            Item item = Item.builder()
                    .itemCode("MAT-004")
                    .effectiveFrom(LocalDate.of(2025, 1, 1))
                    .itemName("材料D")
                    .itemCategory(ItemCategory.MATERIAL)
                    .build();
            itemMapper.insert(item);

            unitPriceMapper.insert(UnitPrice.builder()
                    .itemCode("MAT-004")
                    .supplierCode("SUP-003")
                    .effectiveFrom(LocalDate.of(2025, 1, 1))
