                .supplierCode("SUP-RCV-001")
                .effectiveFrom(LocalDate.of(2025, 1, 1))
                .unitPrice(new BigDecimal("1000"))
                .build());

        // テスト用発注を作成
        PurchaseOrderCreateInput poInput = PurchaseOrderCreateInput.builder()
                .supplierCode("SUP-RCV-001")
                .orderDate(LocalDate.of(2025, 1, 15))
                .details(List.of(
