            #{manufactureDate}, #{expirationDate}, #{quantity}, #{warehouseCode}, #{remarks}
        )
    &lt;/insert&gt;

    &lt;insert id="insertComposition" useGeneratedKeys="true" keyProperty="id" keyColumn="ID"&gt;
        INSERT INTO "ロット構成" (
