コード例: GrpcCircuitBreaker.java <pre><code>/**
 * gRPC 回路ブレーカー
 */
public class GrpcCircuitBreaker {

    public enum State {
        CLOSED,      // 正常（リクエスト許可）
        OPEN,        // 遮断（リクエスト拒否）
        HALF_OPEN    // 試行中
    }

    private final int failureThreshold;
    private final int successThreshold;
    private final Duration openStateTimeout;

    private volatile State state = State.CLOSED;
    private final AtomicInteger failureCount = new AtomicInteger(0);
    private final AtomicInteger successCount = new AtomicInteger(0);
    private volatile Instant lastFailureTime;

    public boolean allowRequest() {
        return switch (state) {
            case CLOSED -&gt; true;
            case OPEN -&gt; shouldAttemptReset();
            case HALF_OPEN -&gt; true;
        };
    }

    private boolean shouldAttemptReset() {
        if (lastFailureTime == null) {
            return false;
        }
        if (Duration.between(lastFailureTime, Instant.now())
                    .compareTo(openStateTimeout) &gt; 0) {
            state = State.HALF_OPEN;
            return true;
        }
        return false;
    }

    public void recordSuccess() {
        if (state == State.HALF_OPEN) {
            if (successCount.incrementAndGet() &gt;= successThreshold) {
                reset();
            }
        } else {
            failureCount.set(0);
        }
    }

    public void recordFailure() {
        lastFailureTime = Instant.now();
        if (state == State.HALF_OPEN) {
            trip();
        } else if (failureCount.incrementAndGet() &gt;= failureThreshold) {
            trip();
        }
    }

    private void trip() {
        state = State.OPEN;
        failureCount.set(0);
        successCount.set(0);
    }

    private void reset() {
        state = State.CLOSED;
        failureCount.set(0);
        successCount.set(0);
    }
}
</code></pre>

