LoggingInterceptor.java <pre><code>package com.example.accounting.infrastructure.in.grpc.interceptor;

import io.grpc.*;
import net.devh.boot.grpc.server.interceptor.GrpcGlobalServerInterceptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;

import java.util.UUID;

/**
 * gRPC ログインターセプター
 */
@GrpcGlobalServerInterceptor
public class LoggingInterceptor implements ServerInterceptor {

    private static final Logger log = LoggerFactory.getLogger(LoggingInterceptor.class);

    @Override
    public &lt;ReqT, RespT&gt; ServerCall.Listener&lt;ReqT&gt; interceptCall(
            ServerCall&lt;ReqT, RespT&gt; call,
            Metadata headers,
            ServerCallHandler&lt;ReqT, RespT&gt; next) {

        String requestId = UUID.randomUUID().toString();
        String methodName = call.getMethodDescriptor().getFullMethodName();
        long startTime = System.currentTimeMillis();

        MDC.put("requestId", requestId);
        log.info("gRPC Request: method={}", methodName);

        return new ForwardingServerCallListener.SimpleForwardingServerCallListener&lt;ReqT&gt;(
                next.startCall(
                    new ForwardingServerCall.SimpleForwardingServerCall&lt;ReqT, RespT&gt;(call) {
                        @Override
                        public void close(Status status, Metadata trailers) {
                            long duration = System.currentTimeMillis() - startTime;
                            log.info("gRPC Response: method={}, status={}, duration={}ms",
                                     methodName, status.getCode(), duration);
                            MDC.clear();
                            super.close(status, trailers);
                        }
                    },
                    headers
                )
        ) {
            @Override
            public void onMessage(ReqT message) {
                log.debug("gRPC Request message: {}", message);
                super.onMessage(message);
            }
        };
    }
}
