                account(accountCode: "11110") {
                    accountCode
                    accountName
                    bsplCategory
                    debitCreditCategory
                }
            }
            """;

        graphQlTester.document(query)
            .execute()
            .path("account.accountCode")
            .entity(String.class)
            .isEqualTo("11110");
    }

